import{_ as n,l as i,o as e,c as s,v as B,p as c,x as l,d as r,i as h,S as p,b as a}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"学习率与批次缩放律","description":"","frontmatter":{"title":"学习率与批次缩放律","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lr-batch-scaling-law.md","filePath":"llm/lr-batch-scaling-law.md","lastUpdated":1789023840000}'),m={name:"llm/lr-batch-scaling-law.md"};function d(E,t,u,b,_,A){const o=i("Mermaid");return e(),s("div",null,[t[1]||(t[1]=B('<h1 id="学习率与批次缩放律" tabindex="-1">学习率与批次缩放律 <a class="header-anchor" href="#学习率与批次缩放律" aria-label="Permalink to &quot;学习率与批次缩放律&quot;">​</a></h1><div class="epigraph"><p>线性规则把 $\\eta$ 随 batch 放大，是小 batch 一侧的可用起点；越过临界 batch 之后，再线性加 $\\eta$ 只买墙钟，不买 token 效率。</p><footer>—— Goyal et al., Accurate, Large Minibatch SGD, 2017；Shallue et al., Measuring the Effects of Data Parallelism on Neural Network Training, JMLR 2019</footer></div><p><a href="/llm/vocab-scaling-law">上一课</a>说明 \\(B\\) 若按 token 计，词表会改同样字节对应的 \\(B\\)。缺口转到：主干 <a href="/llm/batch-vs-lr">批次与学习率</a> 已写线性 / \\(\\sqrt{B}\\) 分层，本课不重推临界 batch 的公式，把它放进<strong>缩放实践</strong>：形状与词表已定之后，数据并行把全局 token batch 从 \\(B_0\\) 拉到 \\(B\\)，日程峰值 \\(\\eta\\) 怎么走。Shallue 等人系统测了数据并行对步数与数据效率的影响；Goyal 等人给出带 warmup 的线性规则。下一课才把临界点写成可测的梯度噪声尺度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>SGD 噪声方差 \\(\\sim 1/B\\)。\\(\\eta\\propto B\\) 保持「噪声 × 步长」一类温度，使不同 \\(B\\) 在看过同等数据后接近。Goyal 强调大 \\(\\eta\\) 必须配更长 warmup，否则起步即炸——这与 Post-LN 预热课同方向，但对象是 batch 而不是 LN 位置。Shallue 等人显示：收益在临界规模附近饱和，再加大 \\(B\\) 减少的是 step 数，达到同等损失所需的 <strong>样本数</strong> 不再下降。</p><p>AdamW 不是 SGD：\\(v\\) 随 \\(B\\) 变，大 batch 的 \\(v\\) 更稳，同样 \\(\\eta\\) 的有效步长更大，纯线性比 SGD 更险。因此 LLM 常用 \\(\\sqrt{B}\\) 或更保守。μP 管宽度，不管 \\(B\\)；把 \\(\\eta\\) 按 μP 迁到宽模型后，再改 \\(B\\) 仍要走本课的规则，两张表相乘，不要用一张吃掉另一张。</p><p><span class="marginnote">\\(B=\\) 数据并行 × 微 batch × 序列长 × 累积。改序列长度却沿用旧 \\(\\eta\\)，等于悄悄改了 \\(B\\)。序列长度预热课会再碰到；这里先把定义钉死。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定已稳的原点 \\((B_0,\\eta_0)\\)：</p><ul><li>\\(B\\ll B_{\\mathrm{crit}}\\)：\\(\\eta\\approx\\eta_0\\cdot B/B_0\\) 或略保守；加长 warmup（按 token）。</li><li>\\(B\\sim B_{\\mathrm{crit}}\\)：改 \\(\\sqrt{B}\\) 或不增加 \\(\\eta\\)；目标从 token 效率改为利用率。</li><li>日程按 <strong>token</strong> 对齐还是按 <strong>step</strong> 对齐必须声明：加大 \\(B\\) 时，按 token 对齐会让余弦更快走完高峰。</li></ul><p>原点必须带模型、词表、优化器、稳定件。从论文抄 3e-4 再按你的 4M token 线性放大，没有 \\(B_0\\)，是无量纲口号。换 \\(|V|\\) 后 \\(B_0\\) 的字节含义变了，应重新标定原点，不要跨词表继承线性系数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>大 \\(B\\) 降噪，更新更接近真梯度；过小噪声减少逃离尖鞍的机会，最终损失有时略差——Shallue 的饱和区包含这种质量代价。线性加 \\(\\eta\\) 是在饱和区之前补偿「每步看更多、每步应走更远」。Adam 的 \\(v\\) 额外放大有效步长，所以 LLM 在尚未测 \\(B_{\\mathrm{crit}}\\) 时宁可 \\(\\sqrt{B}\\)。触顶率（梯度范数课）是实践中的饱和传感器：线性加 \\(\\eta\\) 之后若持续贴顶，你已经越过临界或稳定件不够。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不测 \\(B_{\\mathrm{crit}}\\) 的公式，下一课用噪声尺度测。也不处理序列长度课程学习以外的「动态 \\(B\\)」。MoE 专家看见的有效 batch 因 drop 变小，专家参数的 \\(B_{\\mathrm{crit}}\\) 可以与稠密层不同，不要共用一个线性系数。</p><p>梯度累积改变的是 \\(B\\) 的实现，不是另一条定律：累积满了才更新时，公式里的 \\(B\\) 用累积后的全局 token 数。日志若只写 per-GPU micro-batch，换卡数之后线性规则会对错原点。</p>',16)),(e(),c(p,null,{default:l(()=>[h(o,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20B0%5B%22%E5%8E%9F%E7%82%B9%20B0%2C%20eta0%22%5D%20--%3E%20REL%7B%22%E7%9B%B8%E5%AF%B9%E4%B8%B4%E7%95%8C%20batch%22%7D%0A%20%20REL%20--%3E%7C%22%E8%BF%9C%E5%B0%8F%E4%BA%8E%22%7C%20LIN%5B%22eta%20%E8%BF%91%E7%BA%BF%E6%80%A7%20%2B%20%E6%9B%B4%E9%95%BF%20warmup%22%5D%0A%20%20REL%20--%3E%7C%22%E8%B6%85%E8%BF%87%22%7C%20SAT%5B%22%E5%81%9C%E5%A2%9E%E6%88%96%20sqrt%EF%BC%9B%E5%8F%AA%E4%B9%B0%E5%A2%99%E9%92%9F%22%5D%0A%20%20LIN%20--%3E%20ALG%5B%22%E6%97%A5%E7%A8%8B%E6%8C%89%20token%20%E6%88%96%20step%20%E5%A3%B0%E6%98%8E%22%5D%0A%20%20SAT%20--%3E%20ALG%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[r(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a("h2",{id:"小结",tabindex:"-1"},[r("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),t[3]||(t[3]=a("ul",null,[a("li",null,"线性规则只在临界 batch 之下是 token 效率工具；之上只换墙钟。"),a("li",null,"AdamW 上 \\(\\sqrt{B}\\) 往往比纯线性更稳；\\(v\\) 随 \\(B\\) 构成额外放大。"),a("li",null,"μP 与 batch 规则相乘，原点必须含词表与稳定件。"),a("li",null,"\\(B\\) 的定义含序列长；改 \\(n\\) 即改 \\(B\\)。"),a("li",null,"累积步计入 \\(B\\)；只写 micro-batch 会把线性规则的原点写错。"),a("li",null,"出处：Goyal et al., 2017；Shallue et al., JMLR 2019。")],-1))])}const g=n(m,[["render",d]]);export{k as __pageData,g as default};
